def dice_loss(logits, target, eps=1.0):
    probs = logits.softmax(1)
    t = F.one_hot(target, logits.shape[1]).permute(0, 3, 1, 2).float()
    inter = (probs * t).sum(dim=(0, 2, 3))
    denom = probs.sum(dim=(0, 2, 3)) + t.sum(dim=(0, 2, 3))
    return 1 - ((2 * inter + eps) / (denom + eps)).mean()

def seg_loss(logits, target, w=0.5):
    # CE gives per-pixel gradient everywhere; Dice directly optimizes overlap and is
    # insensitive to class imbalance (a 1%-foreground mask kills plain CE).
    return (1 - w) * F.cross_entropy(logits, target) + w * dice_loss(logits, target)

