def parse(words, predict_action):
    stack = ['ROOT']
    buffer = list(words)
    arcs = []                                        # (head, dependent) pairs
    while buffer or len(stack) > 1:
        action = predict_action(stack, buffer, arcs) # a classifier picks the action
        if action == 'SHIFT' and buffer:
            stack.append(buffer.pop(0))
        elif action == 'LEFT-ARC' and len(stack) >= 2:
            arcs.append((stack[-1], stack[-2]))       # top is head of second
            stack.pop(-2)
        elif action == 'RIGHT-ARC' and len(stack) >= 2:
            arcs.append((stack[-2], stack[-1]))       # second is head of top
            stack.pop()
        else:
            if buffer: stack.append(buffer.pop(0))
    return arcs

