def lasso_cd(X, y, lam, sweeps=1000, tol=1e-10):
    n, p = X.shape
    beta = np.zeros(p)
    resid = y.copy()                 # keep the residual, never recompute it
    colsq = (X ** 2).sum(axis=0)
    for _ in range(sweeps):
        move = 0.0
        for j in range(p):
            old = beta[j]
            # add column j back in, then re-solve for it exactly
            rho = X[:, j] @ (resid + X[:, j] * old)
            beta[j] = soft(rho, lam) / colsq[j]
            if beta[j] != old:
                resid -= X[:, j] * (beta[j] - old)
                move = max(move, abs(beta[j] - old))
        if move < tol:
            break
    return beta

