def fista(X, y, lam, iters=1000, accelerate=True):
    L = np.linalg.norm(X.T @ X, 2)          # Lipschitz constant of the gradient
    x = np.zeros(X.shape[1])
    z, t = x.copy(), 1.0
    for _ in range(iters):
        grad = X.T @ (X @ z - y)
        x_new = soft(z - grad / L, lam / L)  # gradient step, then prox
        if accelerate:
            t_new = (1 + np.sqrt(1 + 4 * t * t)) / 2
            z = x_new + ((t - 1) / t_new) * (x_new - x)   # Nesterov extrapolation
            t = t_new
        else:
            z = x_new
        x = x_new
    return x

