def cfr(history, p0, p1, node_map):
    if is_terminal(history):
        return payoff(history)
    info_set = node_map[abstract(history)]
    strategy = info_set.regret_matching()
    util = [0.0] * n_actions
    node_util = 0.0
    for a in range(n_actions):
        # recurse with the ACTING player's reach probability scaled by this action
        if player(history) == 0:
            util[a] = -cfr(history + [a], p0 * strategy[a], p1, node_map)
        else:
