        prefix.append(sample(residual(p[i], q[i])))
        break                                    # stop at first rejection

import numpy as np
from scipy.stats import norm, beta

def certify(model, x, sigma, n=10000, alpha=0.001):
    votes = np.bincount([model(x + np.random.randn(*x.shape) * sigma).argmax()
                         for _ in range(n)])
    top = votes.argmax()
    # Clopper-Pearson LOWER bound, not votes.max()/n. This is the whole certificate.
    p_lower = beta.ppf(alpha, votes[top], n - votes[top] + 1)
    if p_lower <= 0.5:
        return None, None                 # abstain: no radius can be claimed
    return top, sigma * norm.ppf(p_lower)

import torch, torch.nn as nn

class SAE(nn.Module):
    def __init__(self, d_model, d_hidden):        # d_hidden >> d_model
        super().__init__()
        self.enc = nn.Linear(d_model, d_hidden)
        self.dec = nn.Linear(d_hidden, d_model, bias=False)

    def forward(self, x):
        z = torch.relu(self.enc(x))
        with torch.no_grad():                     # keep the dictionary unit-norm
            self.dec.weight.div_(self.dec.weight.norm(dim=0, keepdim=True))
        return self.dec(z), z

def loss_fn(x, x_hat, z, lam=1e-3):
    return ((x - x_hat) ** 2).sum(-1).mean() + lam * z.abs().sum(-1).mean()

from collections import deque

def revise(domains, i, j, compatible):
    """Drop values of i that have no support left in j."""
    removed = False
    for a in list(domains[i]):
        if not any(compatible(a, b) for b in domains[j]):
            domains[i].discard(a)
            removed = True
    return removed

def ac3(domains, arcs, neighbours, compatible):
    queue = deque(arcs)
    while queue:
        i, j = queue.popleft()
        if revise(domains, i, j, compatible):
            if not domains[i]:
                return False                      # a wipe-out proves unsatisfiability
            for k in neighbours[i]:
                if k != j:
                    queue.append((k, i))          # i shrank, so re-check its supporters
    return True

def solve(assignment, domains, constraints):
    if len(assignment) == len(domains):
        return assignment
    # Most-constrained variable first: fail fast, prune more.
    var = min((v for v in domains if v not in assignment),
              key=lambda v: len(domains[v]))
    for value in domains[var]:
        if all(c(assignment, var, value) for c in constraints):
            assignment[var] = value
            result = solve(assignment, domains, constraints)
            if result:
                return result
            del assignment[var]          # UNDO - this is the backtrack
        # else: pruned without recursing at all
    return None

def knapsack_bb(items, cap):
    # order by value density: makes the fractional bound tight and finds good
    # incumbents early, which is what makes the pruning bite
    items = sorted(items, key=lambda it: it.v / it.w, reverse=True)
    best = 0

    def bound(i, w, v):
        bw, bv = w, v
        for j in range(i, len(items)):
            if bw + items[j].w <= cap:
                bw += items[j].w; bv += items[j].v
            else:
                bv += (cap - bw) * items[j].v / items[j].w   # fractional tail
                break
        return bv

    def rec(i, w, v):
        nonlocal best
        best = max(best, v)
        if i == len(items):
            return
        if bound(i, w, v) <= best:      # PRUNE: nothing below can beat the incumbent
            return
        if w + items[i].w <= cap:
            rec(i + 1, w + items[i].w, v + items[i].v)   # take it (explore first)
        rec(i + 1, w, v)                                 # leave it
    rec(0, 0, 0)
    return best

import heapq

def dijkstra(graph, src):
    dist = {src: 0}
    pq = [(0, src)]
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist.get(u, float("inf")):
            continue                       # a stale entry; the good one already ran
        for v, w in graph[u]:
            nd = d + w
            if nd < dist.get(v, float("inf")):
                dist[v] = nd
                heapq.heappush(pq, (nd, v))
    return dist

def edit_distance(a, b):
    prev = list(range(len(b) + 1))
    for i, ca in enumerate(a, 1):
        cur = [i]
        for j, cb in enumerate(b, 1):
            cur.append(min(prev[j] + 1, cur[j-1] + 1, prev[j-1] + (ca != cb)))
        prev = cur
    return prev[-1]

