from collections import deque

def max_flow(cap, s, t):                   # cap: dict-of-dicts, mutated into residual
    flow = 0
    while True:
        parent = {s: s}
        q = deque([s])
        while q and t not in parent:       # BFS => shortest augmenting path (Edmonds-Karp)
            u = q.popleft()
            for v, c in cap[u].items():
                if c > 0 and v not in parent:
                    parent[v] = u
                    q.append(v)
        if t not in parent:
            break
        bottleneck, v = float("inf"), t
        while v != s:
            bottleneck = min(bottleneck, cap[parent[v]][v]); v = parent[v]
        v = t
        while v != s:
            cap[parent[v]][v] -= bottleneck
            cap[v][parent[v]] = cap[v].get(parent[v], 0) + bottleneck   # residual
            v = parent[v]
        flow += bottleneck
    return flow, parent            # vertices reachable at the end = the min cut's S side

def kruskal(n, edges):                     # edges: (weight, u, v)
    parent = list(range(n))
    rank = [0] * n

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]  # path halving
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra == rb:
            return False                   # already connected: this edge makes a cycle
        if rank[ra] < rank[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        rank[ra] += rank[ra] == rank[rb]
        return True

    tree, total = [], 0
    for w, u, v in sorted(edges):          # the sort dominates: O(E log E)
        if union(u, v):
            tree.append((u, v, w))
            total += w
    return tree, total

import heapq

def astar(start, goal, neighbors, cost, h):
    frontier = [(h(start), 0, start)]
    best = {start: 0}
    came = {}
    while frontier:
        _, g, node = heapq.heappop(frontier)
        if node == goal:
            return best[goal], came
        if g > best.get(node, float("inf")):
            continue                      # a better route to this node already ran
        for nxt in neighbors(node):
            ng = g + cost(node, nxt)
            if ng < best.get(nxt, float("inf")):
                best[nxt] = ng
                came[nxt] = node
                heapq.heappush(frontier, (ng + h(nxt), ng, nxt))
    return None, came
